import re
import sys
from lxml import etree


def get_etree_html_object(xml_content):
    if sys.version.startswith("2"):
        return etree.HTML(xml_content)
    else:
        return etree.HTML(xml_content.encode())


def is_node_in_xml(xml_content, node_text):
    node_text = node_text.replace("&", "&amp;")
    return 'text="{}"'.format(node_text) in xml_content


def get_node_bounds(xml_content, node_text):
    nodes = _search_nodes_with_text(xml_content, node_text)
    if not nodes or len(nodes) > 1:
        raise Exception(nodes)
    return _get_node_bounds(nodes[0])


def get_enabled_node_bounds(xml_content, node_text, node_index=0):
    nodes = _search_nodes_with_text(xml_content, node_text)
    nodes = [node for node in nodes if node.get("enabled") == 'true']
    if not nodes:
        raise Exception(nodes)
    return _get_node_bounds(nodes[node_index])


def _search_nodes_with_text(xml_content, node_text):
    xml_obj = get_etree_html_object(xml_content)
    return xml_obj.xpath('//node[@text="{}"]'.format(node_text))


def search_nodes_with_resource_id(xml_content, resource_id):
    xml_obj = get_etree_html_object(xml_content)
    return xml_obj.xpath('//node[@resource-id="{}"]'.format(resource_id))


def _get_node_bounds(node):
    bounds = node.attrib['bounds']
    bound_postions = []
    for postion in bounds.lstrip("[").rstrip("]").split("]["):
        bound_postions.append([int(value) for value in postion.split(",")])
    return bound_postions


def get_nodes_select_status(xml_content):
    xml_obj = get_etree_html_object(xml_content)
    raido_button_nodes = xml_obj.xpath(r'//node[@resource-id="com.android.settings:id/apn_radiobutton"]')
    title_nodes = xml_obj.xpath(r'//node[@resource-id="android:id/title"]')

    nodes_select_status = {}
    for radio_button in raido_button_nodes:
        radio_button_start_y = _get_node_bounds(radio_button)[0][1]
        is_raido_button_selected = radio_button.get("checked") == 'true'
        for title_node in title_nodes:
            title_node_start_y = _get_node_bounds(title_node)[0][1]
            if radio_button_start_y == title_node_start_y:
                nodes_select_status[title_node.get("text")] = is_raido_button_selected
                break
    return nodes_select_status


def get_selected_node_title(xml_content):
    nodes_select_status = get_nodes_select_status(xml_content)
    for node_title, is_selected in nodes_select_status.items():
        if is_selected:
            return node_title
    return None


def get_selected_node_title_in_dialog(xml_content):
    xml_obj = get_etree_html_object(xml_content)
    nodes = xml_obj.xpath(r'//node[@resource-id="android:id/text1"]')
    for each_node in nodes:
        if each_node.get("checked") == "true":
            return each_node.get("text")
    return None


def remove_escape_sequences(input_str):
    compiled_pattern = re.compile(br'''
    (?: # either 7-bit C1, two bytes, ESC Fe (omitting CSI)
        \x1B
        [@-Z\\-_]
    |   # or a single 8-bit byte Fe (omitting CSI)
        [\x08\x80-\x9A\x9C-\x9F]
    |   # or CSI + control codes
        (?: # 7-bit CSI, ESC [
            \x1B\[
        |   # 8-bit CSI, 9B
            \x9B
        )
        [0-?]*  # Parameter bytes
        [ -/]*  # Intermediate bytes
        [@-~]   # Final byte
    )''', re.VERBOSE)

    output_str = compiled_pattern.sub('', input_str)
    return output_str.strip()


def get_checkedtextview_nodes(xml_content):
    xml_obj = get_etree_html_object(xml_content)
    return xml_obj.xpath('//node[@class="android.widget.CheckedTextView"]')


def get_selected_checkedtextview_node(nodes):
    for node in nodes:
        if node.get("checked") == "true":
            return node
    return None


def get_radio_node_bounds_by_title(xml_content, title):
    xml_obj = get_etree_html_object(xml_content)
    node = xml_obj.xpath('//node[@text="{}"]/../../node[@class="android.widget.RadioButton"]'.format(title))[0]
    return _get_node_bounds(node)


def fetch_node_bounds(node):
    return _get_node_bounds(node)


def get_widgetswitch_nodes(xml_content):
    xml_obj = get_etree_html_object(xml_content)
    return xml_obj.xpath('//node[@class="android.widget.Switch"]')


def get_nodes_by_filter(xml_content, xpath_filter):
    xml_obj = get_etree_html_object(xml_content)
    return xml_obj.xpath(xpath_filter)


def get_checked_node_text(nodes):
    for node in nodes:
        if node.get("checked") == 'true':
            return node.get("text")
    return None
